   let time = initialTime;
   let nextTimerId = 1;
   const timers = new Map();

   return {
     now: () => time,
     setTime(value) {
       time = value;
     },
     setTimeoutFn(callback, delay) {
       const timerId = nextTimerId++;
       timers.set(timerId, { callback, delay });
       return timerId;
     },
     clearTimeoutFn(timerId) {
       timers.delete(timerId);
